package net.officefloor.hq.app.pool;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.crew.Crew;
import net.officefloor.hq.app.crew.CrewRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the pools of a sheet, each name at most once, and their members: each person at most once in a pool, with a
 * share percent above 0.00 and at most 100.00, and optionally a from-date and a to-date not before it. A person may be in several pools. A pool may be a member of another
 * pool, of at most one, never containing itself through any chain, and a chain of pools is at most three deep.
 */
@Service
public class PoolService {

    static final BigDecimal MAX_SHARE = new BigDecimal("100.00");

    /** The most pools in a chain of pools, each a member of the next. */
    static final int MAX_DEPTH = 3;

    private final PoolRepository pools;
    private final CrewRepository crews;
    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Audit audit;

    public PoolService(PoolRepository pools, CrewRepository crews, PersonRepository people, SheetRepository sheets,
            Audit audit) {
        this.pools = pools;
        this.crews = crews;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Pool> list(String sheetId) {
        return pools.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** The sheet's crews, in the order they were added: each is also a pool, under its name. */
    @Transactional(readOnly = true)
    public List<Crew> crews(String sheetId) {
        return crews.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add a pool by its name (already trimmed, not blank); refused when the sheet has a pool or a crew by that name. */
    @Transactional
    public Pool add(String sheetId, String user, String name) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        if (pools.existsBySheetIdAndName(sheetId, name)) {
            throw new PoolRefusedException(name + " is already a pool on sheet " + sheetId);
        }
        if (crews.existsBySheetIdAndName(sheetId, name)) {
            throw new PoolRefusedException(name + " is a crew, and so a pool, on sheet " + sheetId);
        }
        Pool saved;
        try {
            saved = pools.saveAndFlush(new Pool(sheetId, name));
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(name + " is already a pool on sheet " + sheetId);
        }
        audit.recordOnCommit("POOL_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName());
        return saved;
    }

    /** Add the person to the pool with the share (two decimals); refused when already in it or the share is out of range. */
    @Transactional
    public Pool addMember(String sheetId, String user, Long poolId, Long personId, BigDecimal share,
            LocalDate from, LocalDate to) {
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + poolId + " on sheet " + sheetId));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new PoolRefusedException("A membership's to-date is not before its from-date");
        }
        if (pool.hasMember(personId)) {
            throw new PoolRefusedException(person.getName() + " is already in pool " + pool.getName());
        }
        BigDecimal scaled = share.setScale(2);
        PoolMember added = new PoolMember(personId, scaled);
        added.setDates(from, to);
        pool.getMembers().add(added);
        try {
            pools.saveAndFlush(pool);
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(person.getName() + " is already in pool " + pool.getName());
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + person.getName() + " share=" + scaled.toPlainString() + dates(from, to));
        return pool;
    }

    /**
     * Add another pool of the sheet to the pool as a member with the share (two decimals); refused when the share is out
     * of range, when the member is already in a pool, when the pool would then contain itself through any chain, or
     * when a chain of pools would then be more than three deep.
     */
    @Transactional
    public Pool addMemberPool(String sheetId, String user, Long poolId, Long memberPoolId,
            BigDecimal share, LocalDate from, LocalDate to) {
        Pool pool = pools.findByIdAndSheetId(poolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + poolId + " on sheet " + sheetId));
        Pool member = pools.findByIdAndSheetId(memberPoolId, sheetId)
                .orElseThrow(() -> new PoolRefusedException("No pool " + memberPoolId + " on sheet " + sheetId));
        if (share.scale() > 2 || share.signum() <= 0 || share.compareTo(MAX_SHARE) > 0) {
            throw new PoolRefusedException("A share is more than 0.00 and at most 100.00, with two decimals");
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new PoolRefusedException("A membership's to-date is not before its from-date");
        }
        List<Pool> all = pools.findBySheetIdOrderByIdAsc(sheetId);
        // Each pool that is a member of another, by the pool above it.
        Map<Long, Long> above = new HashMap<>();
        for (Pool p : all) {
            for (PoolMember m : p.getMembers()) {
                if (m.getMemberPoolId() != null) {
                    above.put(m.getMemberPoolId(), p.getId());
                }
            }
        }
        if (above.containsKey(memberPoolId)) {
            throw new PoolRefusedException(member.getName() + " is already a member of a pool");
        }
        // Levels from the top down to the pool (the pool itself counting one); a chain from the member back to the
        // pool would contain the pool in itself.
        int levels = 0;
        for (Long at = poolId; at != null; at = above.get(at)) {
            if (at.equals(memberPoolId)) {
                throw new PoolRefusedException(pool.getName() + " may not contain itself");
            }
            levels++;
        }
        if (levels + height(memberPoolId, all) > MAX_DEPTH) {
            throw new PoolRefusedException("A chain of pools is at most " + MAX_DEPTH + " deep");
        }
        BigDecimal scaled = share.setScale(2);
        PoolMember added = PoolMember.ofPool(memberPoolId, scaled);
        added.setDates(from, to);
        pool.getMembers().add(added);
        try {
            pools.saveAndFlush(pool);
        } catch (DataIntegrityViolationException e) {
            throw new PoolRefusedException(member.getName() + " is already a member of a pool");
        }
        audit.recordOnCommit("POOL_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " pool=" + pool.getName()
                + " name=" + member.getName() + " share=" + scaled.toPlainString() + dates(from, to));
        return pool;
    }

    /** The membership's dates for the audit, each only when given. */
    private static String dates(LocalDate from, LocalDate to) {
        return (from != null ? " from=" + from : "") + (to != null ? " to=" + to : "");
    }

    /** The levels of pools from this one down its deepest chain of member pools, itself counting one. */
    private static int height(Long poolId, List<Pool> all) {
        Pool pool = all.stream().filter(p -> p.getId().equals(poolId)).findFirst().orElse(null);
        int below = 0;
        if (pool != null) {
            for (PoolMember m : pool.getMembers()) {
                if (m.getMemberPoolId() != null) {
                    below = Math.max(below, height(m.getMemberPoolId(), all));
                }
            }
        }
        return 1 + below;
    }
}
package net.officefloor.hq.app.crew;

import java.util.HashSet;
import java.util.List;
import java.util.Set;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.pool.PoolRepository;
import net.officefloor.hq.app.person.PersonNotFoundException;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.sheet.SheetNotFoundException;
import net.officefloor.hq.app.sheet.SheetRepository;
import org.springframework.dao.DataIntegrityViolationException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

/**
 * Keeps the crews of a sheet, each name at most once, each with a lead from the sheet's people, and their members: a
 * person is in a crew at most once, and never as both its lead and a member. A person may be in several crews. A crew
 * is also a pool under its name, so no crew takes a pool's name.
 */
@Service
public class CrewService {

    private final CrewRepository crews;
    private final PoolRepository pools;
    private final PersonRepository people;
    private final SheetRepository sheets;
    private final Audit audit;

    public CrewService(CrewRepository crews, PoolRepository pools, PersonRepository people, SheetRepository sheets,
            Audit audit) {
        this.crews = crews;
        this.pools = pools;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<Crew> list(String sheetId) {
        return crews.findBySheetIdOrderByIdAsc(sheetId);
    }

    /**
     * The people a restricted user sees: the person with the user's name, and the lead and members of every crew that
     * person leads or belongs to; none when the sheet has no person by that name.
     */
    @Transactional(readOnly = true)
    public Set<Long> peopleOf(String sheetId, String user) {
        Set<Long> ids = new HashSet<>();
        people.findBySheetIdAndNameKey(sheetId, Person.key(user)).ifPresent(self -> {
            ids.add(self.getId());
            for (Crew crew : crews.findBySheetIdOrderByIdAsc(sheetId)) {
                if (crew.includes(self.getId())) {
                    if (crew.getLeadId() != null) {
                        ids.add(crew.getLeadId());
                    }
                    crew.getMembers().forEach(m -> ids.add(m.getPersonId()));
                }
            }
        });
        return ids;
    }

    /** Add a crew by its name (already trimmed, not blank) with its lead; refused when the sheet has a crew or a pool by that name. */
    @Transactional
    public Crew add(String sheetId, String user, String name, Long leadId) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException(sheetId);
        }
        Person lead = people.findByIdAndSheetId(leadId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, leadId));
        if (crews.existsBySheetIdAndName(sheetId, name)) {
            throw new CrewRefusedException(name + " is already a crew on sheet " + sheetId);
        }
        if (pools.existsBySheetIdAndName(sheetId, name)) {
            throw new CrewRefusedException(name + " is already a pool on sheet " + sheetId);
        }
        Crew saved;
        try {
            saved = crews.saveAndFlush(new Crew(sheetId, name, leadId));
        } catch (DataIntegrityViolationException e) {
            throw new CrewRefusedException(name + " is already a crew on sheet " + sheetId);
        }
        audit.recordOnCommit("CREW_ADDED sheet=" + sheetId + " by=" + user + " name=" + saved.getName()
                + " lead=" + lead.getName());
        return saved;
    }

    /** Add the person to the crew; refused when they are its lead or already a member. */
    @Transactional
    public Crew addMember(String sheetId, String user, Long crewId, Long personId) {
        Crew crew = crews.findByIdAndSheetId(crewId, sheetId)
                .orElseThrow(() -> new CrewRefusedException("No crew " + crewId + " on sheet " + sheetId));
        Person person = people.findByIdAndSheetId(personId, sheetId)
                .orElseThrow(() -> new PersonNotFoundException(sheetId, personId));
        if (personId.equals(crew.getLeadId())) {
            throw new CrewRefusedException(person.getName() + " leads crew " + crew.getName());
        }
        if (crew.includes(personId)) {
            throw new CrewRefusedException(person.getName() + " is already in crew " + crew.getName());
        }
        crew.getMembers().add(new CrewMember(personId));
        try {
            crews.saveAndFlush(crew);
        } catch (DataIntegrityViolationException e) {
            throw new CrewRefusedException(person.getName() + " is already in crew " + crew.getName());
        }
        audit.recordOnCommit("CREW_MEMBER_ADDED sheet=" + sheetId + " by=" + user + " crew=" + crew.getName()
                + " name=" + person.getName());
        return crew;
    }
}

